\mathsf{Rule}_{\mathsf{PLL}}
=\mathsf{Rule}_{1}\cup\mathsf{Rule}_{0}\cup\mathsf{Rule}_{\otimes}
\cup\bigcup_{k<2}\mathsf{Rule}_{\oplus k}
\cup\mathsf{Rule}_{\downarrow}\cup\mathsf{Rule}_{\mathsf{decide}}
\cup\bigcup_{X\in\{U,F\}}
(\mathsf{Rule}_{\mathbin{⅋} X}\cup\mathsf{Rule}_{\& X}\cup
\mathsf{Rule}_{\bot X}\cup\mathsf{Rule}_{\top X}\cup\mathsf{Rule}_{\uparrow X}),

\mathsf{TreeCode}_{\mathsf{PLL}}
=\bigcup_{n\in\mathbb N,\ n>0}
\{n\}\times n\times\mathcal P(n\times n)
\times(n^{<\omega})^n\times(\mathsf{Jud}_{\mathsf{PLL}})^n,
\qquad n^{<\omega}=\bigcup_{k\in\mathbb N}n^k.
